from lib import *
T = "Comparison"
# ---- A2.1: short adjectives, one clear form, everyday words
mc(T,"A2.1",1,"Choose the correct form: My bag is ___ than your bag.","heavier",["heavy","more heavy","heavyer"],"*Heavy* ends in *-y*: *heavy → heavier*, then *than*.","*Heavy* beidzas ar *-y*: *heavy → heavier*, pēc tam *than*.")
mc(T,"A2.1",1,"Choose the correct word: This film is ___ than the book.","better",["gooder","more good","best"],"*Good* is irregular: *good → better*.","*Good* ir neregulārs: *good → better*.")
mc(T,"A2.1",1,"Choose the correct form: Anna is the ___ girl in our class.","tallest",["taller","most tall","more tall"],"With one-syllable words: *the* + adjective + *-est*: *the tallest*.","Ar vienas zilbes vārdiem: *the* + īpašības vārds + *-est*: *the tallest*.")
mc(T,"A2.1",1,"Choose the correct form: Our flat is ___ than their flat.","newer",["more new","newest","new than"],"Short adjective: *new → newer*, then *than*.","Īss īpašības vārds: *new → newer*, pēc tam *than*.")
mc(T,"A2.1",1,"Choose the correct word: Mount Everest is ___ highest mountain in the world.","the",["a","more","most"],"We use *the* before a superlative: *the highest*.","Pirms vispārākās pakāpes lieto *the*: *the highest*.")
mc(T,"A2.1",2,"Which sentence compares two things?","My car is smaller than yours.",["My car is the smallest in the street.","My car is very small.","My car is small and red."],"*Smaller than* compares two things.","*Smaller than* salīdzina divas lietas.")
gp(T,"A2.1",3,"A bus is ___ than a taxi. (cheap)","cheaper","One syllable: *cheap + -er = cheaper*.","Viena zilbe: *cheap + -er = cheaper*.")
gp(T,"A2.1",3,"Today is ___ than yesterday. (hot)","hotter","Short word ending in vowel + consonant: double the last letter: *hot → hotter*.","Īss vārds, kas beidzas ar patskani un līdzskani: dubulto pēdējo burtu: *hot → hotter*.")
gp(T,"A2.1",3,"This is the ___ cake in the shop. (big)","biggest","Double the last letter: *big → the biggest*.","Dubulto pēdējo burtu: *big → the biggest*.")
gp(T,"A2.1",3,"She is ___ student in our group. (good)","the best","The superlative of *good* is *the best*.","*Good* vispārākā pakāpe ir *the best*.")
mc(T,"A2.1",4,"At home: which sentence is NOT correct?","She is more tall than her brother.",["She is taller than her brother.","He is the youngest in the family.","This bag is lighter than that one."],"One-syllable adjectives take *-er*: *taller*, not *more tall*.","Vienas zilbes īpašības vārdiem pievieno *-er*: *taller*, nevis *more tall*.")
tx(T,"A2.1",3,"Write one sentence with older and than: Tom is twelve. Ben is ten.","Tom is older than Ben.","Compare with *older than*: *Tom is older than Ben.*","Salīdzini ar *older than*: *Tom is older than Ben.*")
od(T,"A2.1",3,"Put the words in order. Compare two cities.","riga is smaller than london","Subject + *is* + comparative + *than* + the other thing.","Teikuma priekšmets + *is* + salīdzināmā forma + *than* + otra lieta.")
mt(T,"A2.1",2,"Match each adjective with its comparative.",[("big","bigger"),("happy","happier"),("nice","nicer"),("good","better")],"Spelling changes: *big → bigger*, *happy → happier*, *nice → nicer*; *good* is irregular.","Pareizrakstības izmaiņas: *big → bigger*, *happy → happier*, *nice → nicer*; *good* ir neregulārs.")
# ---- A2.2: longer adjectives, as ... as, the same as, in
mc(T,"A2.2",1,"Choose the correct form: This exercise is ___ than the last one.","more difficult",["difficulter","most difficult","more difficulter"],"Long adjectives take *more*: *more difficult than*.","Gariem īpašības vārdiem lieto *more*: *more difficult than*.")
mc(T,"A2.2",2,"Choose the correct form: My phone is ___ yours: they both cost 300 euros.","as expensive as",["more expensive than","the most expensive","as expensive than"],"*as ... as* says two things are equal.","*as ... as* parāda, ka divas lietas ir vienādas.")
mc(T,"A2.2",3,"Choose the correct word: She is the tallest girl ___ her class.","in",["of","from","than"],"After a superlative we use *in* + a place or group: *in her class*.","Aiz vispārākās pakāpes lieto *in* + vieta vai grupa: *in her class*.")
mc(T,"A2.2",2,"Choose the correct word: My shoes are the same ___ yours.","as",["than","like","to"],"We say *the same as*.","Saka *the same as*.")
mc(T,"A2.2",2,"Which sentence means the same as 'My room is bigger than yours'?","Your room is smaller than mine.",["Your room is bigger than mine.","Your room is as big as mine.","Your room is the smallest."],"If my room is bigger, yours is smaller.","Ja mana istaba ir lielāka, tava ir mazāka.")
mc(T,"A2.2",4,"At the market: which sentence is NOT correct?","This is the more interesting book in the shop.",["This book is more interesting than that one.","This is the most interesting book in the shop.","That book is as interesting as this one."],"For three or more things we use *the most*, not *the more*.","Trim vai vairāk lietām lieto *the most*, nevis *the more*.")
gp(T,"A2.2",3,"Gold is ___ than silver. (expensive)","more expensive","Long adjective: *more expensive than*.","Garš īpašības vārds: *more expensive than*.")
gp(T,"A2.2",3,"This is ___ film I have ever seen. (bad)","the worst","The superlative of *bad* is *the worst*.","*Bad* vispārākā pakāpe ir *the worst*.")
gp(T,"A2.2",3,"The train is ___ than the bus. (fast)","faster","One syllable: *fast + -er = faster*.","Viena zilbe: *fast + -er = faster*.")
tx(T,"A2.2",3,"Rewrite with not as ... as: Tom is taller than Sam.",["Sam is not as tall as Tom.","Sam isn't as tall as Tom."],"*not as ... as* says one is less: *Sam is not as tall as Tom.*","*not as ... as* nozīmē mazāk: *Sam is not as tall as Tom.*")
od(T,"A2.2",3,"Put the words in order. Compare two prices.","this jacket is cheaper than that one","Subject + *is* + comparative + *than* + *that one*.","Priekšmets + *is* + salīdzināmā forma + *than* + *that one*.")
mt(T,"A2.2",2,"Match each adjective with its superlative.",[("long","the longest"),("easy","the easiest"),("expensive","the most expensive"),("bad","the worst")],"*-est* for short words, *the most* for long words, and irregular *the worst*.","*-est* īsiem vārdiem, *the most* gariem vārdiem un neregulārais *the worst*.")
# ---- B1.1: longer sentences, much / a bit / far, less ... than, adverbs
mc(T,"B1.1",3,"Choose the correct option: The new hotel is ___ more comfortable than the old one, so we will stay there again.","much",["very","too","more"],"*much* + comparative shows a big difference: *much more comfortable*.","*much* + salīdzināmā forma parāda lielu atšķirību: *much more comfortable*.")
mc(T,"B1.1",3,"Choose the correct option: Travelling by train is a bit ___ than driving, but it is more relaxing.","slower",["more slow","slowest","the slower"],"*a bit* + comparative shows a small difference: *a bit slower*.","*a bit* + salīdzināmā forma parāda nelielu atšķirību: *a bit slower*.")
mc(T,"B1.1",3,"Choose the correct option: She works ___ than her colleagues, so she often finishes late.","harder",["more hard","hardest","hardly"],"*Hard* is also an adverb: *hard → harder*.","*Hard* ir arī apstākļa vārds: *hard → harder*.")
mc(T,"B1.1",3,"Choose the correct option: Of all the students, Maria speaks English ___ .","the most fluently",["more fluently","the more fluent","most fluent"],"Adverbs ending in *-ly* use *the most*: *the most fluently*.","Apstākļa vārdiem ar *-ly* lieto *the most*: *the most fluently*.")
mc(T,"B1.1",2,"Which sentence says the difference is small?","This bag is slightly bigger than that one.",["This bag is much bigger than that one.","This bag is far bigger than that one.","This bag is the biggest in the shop."],"*slightly* and *a bit* show a small difference; *much* and *far* show a big one.","*slightly* un *a bit* parāda nelielu atšķirību; *much* un *far* - lielu.")
mc(T,"B1.1",4,"On the news: which sentence is NOT correct?","The weather today is much more warmer than yesterday.",["The weather today is much warmer than yesterday.","It was the coldest day of the whole winter.","It is not as cold as it was last week."],"We use *warmer* or *more*, never both: *much warmer*.","Lieto *warmer* vai *more*, nekad abus: *much warmer*.")
gp(T,"B1.1",3,"Prices in the city centre are far ___ than in the suburbs. (high)","higher","*far* + comparative: *far higher*.","*far* + salīdzināmā forma: *far higher*.")
gp(T,"B1.1",3,"This printer is ___ expensive than the other one, so I think we should buy it.","less","*less ... than* is the opposite of *more ... than*.","*less ... than* ir pretējs *more ... than*.")
tx(T,"B1.1",5,"Rewrite with less ... than: This flat is more expensive than that flat.",["That flat is less expensive than this flat.","That flat is less expensive than this one."],"Turn it round with *less ... than*: *That flat is less expensive than this flat.*","Apgriez ar *less ... than*: *That flat is less expensive than this flat.*")
tx(T,"B1.1",3,"Rewrite with as ... as: My brother and I are both 1.80 metres tall.",["My brother is as tall as I am.","My brother is as tall as me.","I am as tall as my brother.","I'm as tall as my brother."],"Equal size: *as tall as*.","Vienāds garums: *as tall as*.")
od(T,"B1.1",3,"Put the words in order. Compare two jobs.","this job is much more stressful than my last one","*much* + *more* + adjective + *than* shows a big difference.","*much* + *more* + īpašības vārds + *than* parāda lielu atšķirību.")
mt(T,"B1.1",3,"Match the beginnings with the endings.",[("The new phone is much","faster than the old one."),("The new phone is a bit","heavier than the old one."),("The new phone is not as","cheap as the old one."),("The new phone is the","best one in the shop.")],"*much* = big difference, *a bit* = small difference, *not as ... as* = less, *the best* = top of the group.","*much* = liela atšķirība, *a bit* = maza atšķirība, *not as ... as* = mazāk, *the best* = labākais grupā.")
# ---- B1.2: ever, the more ... the, get + comparative, twice as, by far
mc(T,"B1.2",3,"Choose the correct option: It is the ___ meal I have ever eaten.","best",["better","most good","goodest"],"With *ever* we use a superlative: *the best meal I have ever eaten*.","Ar *ever* lieto vispārāko pakāpi: *the best meal I have ever eaten*.")
mc(T,"B1.2",3,"Choose the correct option: The more I practise, ___ I feel.","the more confident",["more confident","the most confident","the confident"],"*The more ..., the more ...* shows two things that change together.","*The more ..., the more ...* parāda divas lietas, kas mainās kopā.")
gp(T,"B1.2",3,"It is getting ___ and ___ every day. (cold)","colder / colder","*Getting colder and colder* shows a change that continues.","*Getting colder and colder* parāda pārmaiņu, kas turpinās.")
gp(T,"B1.2",3,"Their new office is twice ___ big as the old one.","as","We say *twice as big as*.","Saka *twice as big as*.")
mc(T,"B1.2",4,"In the team: which sentence is NOT correct?","He is by far the more experienced player in the team.",["He is by far the most experienced player in the team.","She is twice as old as her cousin.","Their house is not as big as ours."],"A group of three or more needs *the most experienced*.","Grupai no trim vai vairāk vajag *the most experienced*.")
tx(T,"B1.2",5,"Rewrite with the superlative: No other mountain in this country is as high as Mount Hill.",["Mount Hill is the highest mountain in this country.","Mount Hill is the highest mountain in the country."],"If nothing is higher, it is *the highest*.","Ja nekas nav augstāks, tas ir *the highest*.")
mc(T,"B1.2",4,"What is the difference between 'This book is more interesting than that one' and 'This book is as interesting as that one'?","The first says one is better; the second says they are equal.",["The first says they are equal; the second says one is better.","Both sentences say the same.","The first is about the past; the second is about the future."],"*more ... than* shows a difference; *as ... as* shows equal.","*more ... than* parāda atšķirību; *as ... as* - vienādību.")
od(T,"B1.2",4,"Put the words in order. Compare two years.","this year was not as busy as last year","*not as busy as* says last year was busier.","*not as busy as* nozīmē, ka pērn bija vairāk darba.")
mc(T,"B1.2",5,"Your friend writes: 'My English is more better than last year.' Choose the correct option.","My English is better than last year.",["My English is more good than last year.","My English is the best than last year.","My English is gooder than last year."],"*Better* is already a comparative: no *more*.","*Better* jau ir salīdzināmā forma: bez *more*.")
save("comparison-1.csv")
